-- Explicit unregistered successor. Observation only: no storage, purpose seal or admission.
-- Static finite handlers; SQL whole-row UTC hashes are never canonical DTO hashes.
CREATE FUNCTION public.observe_manual_review_full_owned_source_bindings_v2(refs jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD'
AS $function$
DECLARE
 tenant text:=nullif(current_setting('app.athlete_id',true),'');
 i jsonb; normalized jsonb; normalized_refs jsonb[]:='{}'; expected_keys text[]; keys text[];
 field text; k text; q text; projection text; phase integer; ordinal integer;
 n bigint; principal_count bigint; bytes bigint; maximum bigint; total_bytes bigint:=0; total_rows bigint:=0;
 relations jsonb; facts jsonb[]:='{}'; fact jsonb; result jsonb; result_bytes bigint:=0;
 uuid_pattern constant text:='^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$';
 uuid_fields text[]; cleanup jsonb;
BEGIN
 IF tenant IS NULL THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_TENANT_REQUIRED'; END IF;
 IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') THEN
  RAISE EXCEPTION 'MANUAL_FULL_BINDING_SNAPSHOT_REQUIRED'; END IF;
 IF refs IS NULL OR jsonb_typeof(refs)<>'array' THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_REFS'; END IF;
 IF jsonb_array_length(refs) NOT BETWEEN 1 AND 5000 OR octet_length(refs::text)>4194304 THEN
  RAISE EXCEPTION 'MANUAL_FULL_BINDING_INPUT_BOUND'; END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(refs) LOOP
  IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR jsonb_typeof(i->'kind') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_REF'; END IF;
  k:=i->>'kind';
  CASE k
   WHEN 'race-event' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'plan-snapshot' THEN expected_keys:=ARRAY['kind','sourceId','version'];
   WHEN 'nutrition-plan-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'routine-schedule-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'routine-blueprint-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'routine-occurrence' THEN expected_keys:=ARRAY['kind','sourceId'];
   WHEN 'routine-run' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'session-completion' THEN expected_keys:=ARRAY['kind','planVersionId','revision','sourceId'];
   WHEN 'food-definition-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'recovery-method-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'recovery-strategy-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'supplementary-exercise-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'workout-template-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'supplementary-session-copy' THEN expected_keys:=ARRAY['kind','sessionId','sourceId'];
   WHEN 'activity-canonical-values' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'manual-activity-source' THEN expected_keys:=ARRAY['kind','sourceId','sourceRecordId','sourceRevision'];
   WHEN 'activity-overlay' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'intake-revision' THEN expected_keys:=ARRAY['kind','revisionId','sourceId'];
   WHEN 'checkin-revision' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'checklist-confirmation' THEN expected_keys:=ARRAY['kind','revisionId','runId','sourceId','stepId'];
   WHEN 'routine-timer' THEN expected_keys:=ARRAY['kind','revision','sourceId','stepId'];
   WHEN 'course-revision' THEN expected_keys:=ARRAY['kind','revision','revisionId','sourceId'];
   WHEN 'course-head-descriptor' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'activity-track-descriptor' THEN expected_keys:=ARRAY['kind','revision','sourceId','trackId'];
   WHEN 'resource-text-version' THEN expected_keys:=ARRAY['kind','sourceId','versionId'];
   WHEN 'race-timing-pin-fragment' THEN expected_keys:=ARRAY['kind','revision','sourceId'];
   WHEN 'gallery-descriptor' THEN expected_keys:=ARRAY['accessRevision','kind','sourceId'];
   ELSE RAISE EXCEPTION 'MANUAL_FULL_BINDING_UNKNOWN_KIND';
  END CASE;
  SELECT array_agg(key ORDER BY key COLLATE "C") INTO keys FROM jsonb_object_keys(i) key;
  IF keys IS DISTINCT FROM expected_keys THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_KEYS'; END IF;
  uuid_fields:=CASE WHEN k IN ('plan-snapshot','routine-schedule-version','routine-blueprint-version','routine-occurrence','routine-run','intake-revision','checklist-confirmation','routine-timer','food-definition-version','session-completion') THEN '{}'::text[] ELSE ARRAY['sourceId'] END;
  IF 'planVersionId'=ANY(expected_keys) THEN uuid_fields:=array_append(uuid_fields,'planVersionId'); END IF;
  IF 'revisionId'=ANY(expected_keys) THEN uuid_fields:=array_append(uuid_fields,'revisionId'); END IF;
  IF 'trackId'=ANY(expected_keys) THEN uuid_fields:=array_append(uuid_fields,'trackId'); END IF;
  IF 'versionId'=ANY(expected_keys) AND k NOT IN ('routine-schedule-version','routine-blueprint-version') THEN uuid_fields:=array_append(uuid_fields,'versionId'); END IF;
  FOREACH field IN ARRAY expected_keys LOOP
   IF field='kind' THEN CONTINUE; END IF;
   IF field IN ('revision','version','sourceRevision','accessRevision') THEN
    IF jsonb_typeof(i->field) IS DISTINCT FROM 'number' OR (i->>field)::numeric<>trunc((i->>field)::numeric)
     OR (i->>field)::numeric NOT BETWEEN (CASE WHEN field='version' OR k IN ('race-event','activity-canonical-values','checkin-revision','course-head-descriptor','race-timing-pin-fragment') THEN 1 ELSE 0 END) AND 2147483647
    THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_REVISION'; END IF;
   ELSE
    IF jsonb_typeof(i->field) IS DISTINCT FROM 'string' OR length(i->>field)=0 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_ID'; END IF;
    IF field=ANY(uuid_fields) THEN
     IF lower(i->>field)!~uuid_pattern THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_INVALID_UUID'; END IF;
     i:=jsonb_set(i,ARRAY[field],to_jsonb(lower(i->>field)));
    END IF;
   END IF;
  END LOOP;
  normalized_refs:=array_append(normalized_refs,i);
 END LOOP;
 normalized:=to_jsonb(normalized_refs);
 IF (SELECT count(DISTINCT value) FROM jsonb_array_elements(normalized))<>jsonb_array_length(normalized) THEN
  RAISE EXCEPTION 'MANUAL_FULL_BINDING_DUPLICATE'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(normalized) e WHERE e->>'kind'='race-event')<>1 THEN
  RAISE EXCEPTION 'MANUAL_FULL_BINDING_RACE_ROSTER'; END IF;
 -- All relation groups finish scalar byte/row preflight before any full-row hash pass.
 FOR phase IN 1..2 LOOP
  ordinal:=0;
  FOREACH i IN ARRAY normalized_refs LOOP
   ordinal:=ordinal+1; k:=i->>'kind';
   CASE k
    WHEN 'race-event' THEN q:=$query$SELECT 'current_body'::text AS role, 'race_event'::text AS relation, jsonb_build_array(r.id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.race_event r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision::numeric=($2->>'revision')::numeric AND NOT r.deleted$query$;
    WHEN 'plan-snapshot' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'plan_snapshot'::text AS relation, jsonb_build_array(r.id,r.version) AS key, to_jsonb(r) AS body, true AS principal FROM public.plan_snapshot r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version::numeric=($2->>'version')::numeric$query$;
    WHEN 'nutrition-plan-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'nutrition_plan_version'::text AS relation, jsonb_build_array(r.plan_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.nutrition_plan_version r WHERE r.athlete_id=$1 AND r.plan_id::text=$2->>'sourceId' AND r.plan_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END$query$;
    WHEN 'routine-schedule-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'routine_schedule_version'::text AS relation, jsonb_build_array(r.schedule_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_schedule_version r WHERE r.athlete_id=$1 AND r.schedule_id::text=$2->>'sourceId' AND r.schedule_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END$query$;
    WHEN 'routine-blueprint-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'routine_blueprint_version'::text AS relation, jsonb_build_array(r.routine_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_blueprint_version r WHERE r.athlete_id=$1 AND r.routine_id::text=$2->>'sourceId' AND r.routine_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END$query$;
    WHEN 'routine-occurrence' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'routine_occurrence'::text AS relation, jsonb_build_array(r.id) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_occurrence r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END$query$;
    WHEN 'routine-run' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'routine_run_revision'::text AS relation, jsonb_build_array(r.run_id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_run_revision r WHERE r.athlete_id=$1 AND r.run_id::text=$2->>'sourceId' AND r.run_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.routine_run p WHERE p.athlete_id=r.athlete_id AND p.id=r.run_id)$query$;
    WHEN 'session-completion' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'session_completion_revision'::text AS relation, jsonb_build_array(r.session_id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.session_completion_revision r WHERE r.athlete_id=$1 AND r.session_id=$2->>'sourceId' AND r.revision::numeric=($2->>'revision')::numeric AND r.record_json->>'planVersionId'=$2->>'planVersionId' AND EXISTS(SELECT 1 FROM public.session_completion p WHERE p.athlete_id=r.athlete_id AND p.session_id=r.session_id) AND EXISTS(SELECT 1 FROM public.plan_snapshot p WHERE p.athlete_id=r.athlete_id AND p.id=($2->>'planVersionId')::uuid AND EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p.draft->'sessions')='array' THEN p.draft->'sessions' ELSE '[]'::jsonb END) s WHERE s->>'id'=r.session_id AND s->>'blockId'=r.record_json->'schedule'->>'blockId' AND s->>'date'=r.record_json->'schedule'->>'date' AND s->'localStartTime'=r.record_json->'schedule'->'localStartTime') AND p.draft->>'timezone'=r.record_json->'schedule'->>'timezone')$query$;
    WHEN 'food-definition-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'food_definition_version'::text AS relation, jsonb_build_array(r.food_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.food_definition_version r WHERE r.athlete_id=$1 AND r.food_id::text=$2->>'sourceId' AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END
 UNION ALL
 SELECT 'current_head'::text AS role, 'food_definition_head'::text AS relation, jsonb_build_array(r.food_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.food_definition_head r WHERE r.athlete_id=$1 AND r.food_id::text=$2->>'sourceId' AND EXISTS(SELECT 1 FROM public.food_definition_version v WHERE v.athlete_id=r.athlete_id AND v.food_id=r.food_id AND v.version_id::text=$2->>'versionId')$query$;
    WHEN 'recovery-method-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'recovery_method_version'::text AS relation, jsonb_build_array(r.method_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.recovery_method_version r WHERE r.athlete_id=$1 AND r.method_id::text=$2->>'sourceId' AND r.method_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END
 UNION ALL
 SELECT 'current_head'::text AS role, 'recovery_method_head'::text AS relation, jsonb_build_array(r.method_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.recovery_method_head r WHERE r.athlete_id=$1 AND r.method_id::text=$2->>'sourceId' AND r.method_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.recovery_method_version v WHERE v.athlete_id=r.athlete_id AND v.method_id=r.method_id AND v.version_id::text=$2->>'versionId')$query$;
    WHEN 'recovery-strategy-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'recovery_strategy_version'::text AS relation, jsonb_build_array(r.strategy_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.recovery_strategy_version r WHERE r.athlete_id=$1 AND r.strategy_id::text=$2->>'sourceId' AND r.strategy_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END
 UNION ALL
 SELECT 'current_head'::text AS role, 'recovery_strategy_head'::text AS relation, jsonb_build_array(r.strategy_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.recovery_strategy_head r WHERE r.athlete_id=$1 AND r.strategy_id::text=$2->>'sourceId' AND r.strategy_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.recovery_strategy_version v WHERE v.athlete_id=r.athlete_id AND v.strategy_id=r.strategy_id AND v.version_id::text=$2->>'versionId')$query$;
    WHEN 'supplementary-exercise-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'supplementary_exercise_version'::text AS relation, jsonb_build_array(r.exercise_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.supplementary_exercise_version r WHERE r.athlete_id=$1 AND r.exercise_id::text=$2->>'sourceId' AND r.exercise_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END
 UNION ALL
 SELECT 'current_head'::text AS role, 'supplementary_exercise_head'::text AS relation, jsonb_build_array(r.exercise_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.supplementary_exercise_head r WHERE r.athlete_id=$1 AND r.exercise_id::text=$2->>'sourceId' AND r.exercise_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.supplementary_exercise_version v WHERE v.athlete_id=r.athlete_id AND v.exercise_id=r.exercise_id AND v.version_id::text=$2->>'versionId')$query$;
    WHEN 'workout-template-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'supplementary_routine_version'::text AS relation, jsonb_build_array(r.routine_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.supplementary_routine_version r WHERE r.athlete_id=$1 AND r.routine_id::text=$2->>'sourceId' AND r.routine_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END AND NOT EXISTS(SELECT b->>'id',t->>'id',t->>'exerciseVersionId' FROM jsonb_array_elements(r.record_json->'spec'->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(b->'sets') t EXCEPT SELECT x.block_id,x.target_set_id,x.exercise_version_id::text FROM public.supplementary_routine_target_ref x WHERE x.athlete_id=r.athlete_id AND x.routine_version_id=r.version_id) AND NOT EXISTS(SELECT x.block_id,x.target_set_id,x.exercise_version_id::text FROM public.supplementary_routine_target_ref x WHERE x.athlete_id=r.athlete_id AND x.routine_version_id=r.version_id EXCEPT SELECT b->>'id',t->>'id',t->>'exerciseVersionId' FROM jsonb_array_elements(r.record_json->'spec'->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(b->'sets') t)
 UNION ALL
 SELECT 'target'::text AS role, 'supplementary_routine_target_ref'::text AS relation, jsonb_build_array(r.routine_version_id,r.target_set_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.supplementary_routine_target_ref r WHERE r.athlete_id=$1 AND r.routine_version_id::text=$2->>'versionId' AND r.routine_version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.supplementary_routine_version v WHERE v.athlete_id=r.athlete_id AND v.version_id=r.routine_version_id AND v.routine_id::text=$2->>'sourceId')$query$;
    WHEN 'supplementary-session-copy' THEN q:=$query$SELECT 'source_fragment'::text AS role, 'supplementary_session_link'::text AS relation, jsonb_build_array(r.plan_version_id,r.planned_session_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.supplementary_session_link r WHERE r.athlete_id=$1 AND r.plan_version_id::text=$2->>'sourceId' AND r.plan_version_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.planned_session_id::text=$2->>'sessionId' AND r.content_kind='embedded' AND EXISTS(SELECT 1 FROM public.plan_snapshot p WHERE p.athlete_id=r.athlete_id AND p.id=r.plan_version_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(p.draft->'sessions') s WHERE s->>'id'=r.planned_session_id AND s->>'sport'='strength')) AND NOT EXISTS(SELECT b->>'id',t->>'id',t->>'exerciseVersionId' FROM jsonb_array_elements(r.embedded_spec_json->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(b->'sets') t EXCEPT SELECT x.block_id,x.target_set_id,x.exercise_version_id::text FROM public.supplementary_session_target_ref x WHERE x.athlete_id=r.athlete_id AND x.plan_version_id=r.plan_version_id AND x.planned_session_id=r.planned_session_id) AND NOT EXISTS(SELECT x.block_id,x.target_set_id,x.exercise_version_id::text FROM public.supplementary_session_target_ref x WHERE x.athlete_id=r.athlete_id AND x.plan_version_id=r.plan_version_id AND x.planned_session_id=r.planned_session_id EXCEPT SELECT b->>'id',t->>'id',t->>'exerciseVersionId' FROM jsonb_array_elements(r.embedded_spec_json->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(b->'sets') t)
 UNION ALL
 SELECT 'target'::text AS role, 'supplementary_session_target_ref'::text AS relation, jsonb_build_array(r.plan_version_id,r.planned_session_id,r.target_set_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.supplementary_session_target_ref r WHERE r.athlete_id=$1 AND r.plan_version_id::text=$2->>'sourceId' AND r.plan_version_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.planned_session_id::text=$2->>'sessionId'$query$;
    WHEN 'activity-canonical-values' THEN q:=$query$SELECT 'current_body'::text AS role, 'activity_canonical'::text AS relation, jsonb_build_array(r.id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.activity_canonical r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision::numeric=($2->>'revision')::numeric AND NOT r.deleted
 UNION ALL
 SELECT 'source_head'::text AS role, 'activity_source_head'::text AS relation, jsonb_build_array(r.kind,r.source_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.activity_source_head r WHERE r.athlete_id=$1 AND r.activity_id::text=$2->>'sourceId' AND r.activity_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.activity_canonical a WHERE a.athlete_id=r.athlete_id AND a.id=r.activity_id AND a.revision::numeric=($2->>'revision')::numeric AND NOT a.deleted)
 UNION ALL
 SELECT 'suppression_observation'::text AS role, 'activity_suppression'::text AS relation, jsonb_build_array(r.kind,r.source_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.activity_suppression r WHERE r.athlete_id=$1 AND EXISTS(SELECT 1 FROM public.activity_source_head h WHERE h.athlete_id=r.athlete_id AND h.kind=r.kind AND h.source_id=r.source_id AND h.activity_id::text=$2->>'sourceId')$query$;
    WHEN 'manual-activity-source' THEN q:=$query$SELECT 'immutable_source'::text AS role, 'activity_source_revision'::text AS relation, jsonb_build_array(r.kind,r.source_id,r.source_revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.activity_source_revision r WHERE r.athlete_id=$1 AND r.source_id::text=$2->>'sourceRecordId' AND r.source_revision::numeric=($2->>'sourceRevision')::numeric AND r.kind='manual' AND EXISTS(SELECT 1 FROM public.activity_source_head h JOIN public.activity_canonical a ON a.athlete_id=h.athlete_id AND a.id=h.activity_id WHERE h.athlete_id=r.athlete_id AND h.kind=r.kind AND h.source_id=r.source_id AND h.source_revision=r.source_revision AND h.content_hash=r.content_hash AND h.activity_id::text=$2->>'sourceId' AND NOT a.deleted AND a.original=r.normalized_raw AND NOT EXISTS(SELECT 1 FROM public.activity_suppression z WHERE z.athlete_id=h.athlete_id AND z.kind=h.kind AND z.source_id=h.source_id))
 UNION ALL
 SELECT 'source_head'::text AS role, 'activity_source_head'::text AS relation, jsonb_build_array(r.kind,r.source_id) AS key, to_jsonb(r) AS body, false AS principal FROM public.activity_source_head r WHERE r.athlete_id=$1 AND r.activity_id::text=$2->>'sourceId' AND r.activity_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.kind='manual' AND r.source_id::text=$2->>'sourceRecordId' AND r.source_revision::numeric=($2->>'sourceRevision')::numeric$query$;
    WHEN 'activity-overlay' THEN q:=$query$SELECT 'current_overlay'::text AS role, 'activity_overlay'::text AS relation, jsonb_build_array(r.activity_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.activity_overlay r WHERE r.athlete_id=$1 AND r.activity_id::text=$2->>'sourceId' AND r.activity_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.activity_canonical a WHERE a.athlete_id=r.athlete_id AND a.id=r.activity_id AND a.revision::numeric=($2->>'revision')::numeric AND NOT a.deleted) AND EXISTS(SELECT 1 FROM public.activity_overlay_revision v WHERE v.athlete_id=r.athlete_id AND v.activity_id=r.activity_id AND v.revision::numeric=($2->>'revision')::numeric)
 UNION ALL
 SELECT 'overlay_revision'::text AS role, 'activity_overlay_revision'::text AS relation, jsonb_build_array(r.activity_id,r.revision) AS key, to_jsonb(r) AS body, false AS principal FROM public.activity_overlay_revision r WHERE r.athlete_id=$1 AND r.activity_id::text=$2->>'sourceId' AND r.activity_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision::numeric=($2->>'revision')::numeric$query$;
    WHEN 'intake-revision' THEN q:=$query$SELECT 'immutable_revision'::text AS role, 'intake_entry_revision'::text AS relation, jsonb_build_array(r.intake_id,r.revision_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.intake_entry_revision r WHERE r.athlete_id=$1 AND r.intake_id::text=$2->>'sourceId' AND r.revision_id::text=$2->>'revisionId' AND r.revision_id=CASE WHEN $2->>'revisionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'revisionId')::uuid ELSE NULL END AND r.status='active' AND EXISTS(SELECT 1 FROM public.intake_entry h WHERE h.athlete_id=r.athlete_id AND h.id=r.intake_id AND h.status='active')
 UNION ALL
 SELECT 'current_head'::text AS role, 'intake_entry'::text AS relation, jsonb_build_array(r.id) AS key, to_jsonb(r) AS body, false AS principal FROM public.intake_entry r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId'$query$;
    WHEN 'checkin-revision' THEN q:=$query$SELECT 'immutable_revision'::text AS role, 'check_in_revision'::text AS relation, jsonb_build_array(r.check_in_id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.check_in_revision r WHERE r.athlete_id=$1 AND r.check_in_id::text=$2->>'sourceId' AND r.check_in_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.check_in h WHERE h.athlete_id=r.athlete_id AND h.id=r.check_in_id AND h.revision>=r.revision AND NOT h.deleted)
 UNION ALL
 SELECT 'current_head'::text AS role, 'check_in'::text AS relation, jsonb_build_array(r.id) AS key, to_jsonb(r) AS body, false AS principal FROM public.check_in r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END$query$;
    WHEN 'checklist-confirmation' THEN q:=$query$SELECT 'immutable_report'::text AS role, 'routine_checklist_confirmation'::text AS relation, jsonb_build_array(r.id,r.revision_id,r.run_id,r.step_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_checklist_confirmation r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision_id::text=$2->>'revisionId' AND r.revision_id=CASE WHEN $2->>'revisionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'revisionId')::uuid ELSE NULL END AND r.run_id::text=$2->>'runId' AND r.run_id=CASE WHEN $2->>'runId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'runId')::uuid ELSE NULL END AND r.step_id::text=$2->>'stepId' AND EXISTS(SELECT 1 FROM public.routine_run run JOIN public.routine_blueprint_version b ON b.athlete_id=run.athlete_id AND b.version_id=run.blueprint_version_id WHERE run.athlete_id=r.athlete_id AND run.id=r.run_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(b.record_json->'steps') s WHERE s->>'id'=r.step_id))$query$;
    WHEN 'routine-timer' THEN q:=$query$SELECT 'current_timer'::text AS role, 'routine_step_timer'::text AS relation, jsonb_build_array(r.run_id,r.step_id,r.revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.routine_step_timer r WHERE r.athlete_id=$1 AND r.run_id::text=$2->>'sourceId' AND r.run_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.step_id::text=$2->>'stepId' AND r.revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.routine_run run JOIN public.routine_blueprint_version b ON b.athlete_id=run.athlete_id AND b.version_id=run.blueprint_version_id WHERE run.athlete_id=r.athlete_id AND run.id=r.run_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(b.record_json->'steps') s WHERE s->>'id'=r.step_id))$query$;
    WHEN 'course-revision' THEN q:=$query$SELECT 'immutable_revision'::text AS role, 'course_revision'::text AS relation, jsonb_build_array(r.course_id,r.revision_id,r.course_revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.course_revision r WHERE r.athlete_id=$1 AND r.course_id::text=$2->>'sourceId' AND r.course_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.revision_id::text=$2->>'revisionId' AND r.revision_id=CASE WHEN $2->>'revisionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'revisionId')::uuid ELSE NULL END AND r.course_revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.course h WHERE h.athlete_id=r.athlete_id AND h.course_id=r.course_id AND h.status='available') AND NOT EXISTS(SELECT 1 FROM public.export_course_deletions() d WHERE d.athlete_id=r.athlete_id AND d.course_id=r.course_id)
 UNION ALL
 SELECT 'lineage'::text AS role, 'course_revision_source'::text AS relation, jsonb_build_array(r.course_id,r.course_revision,r.activity_id,r.track_id,r.track_revision) AS key, to_jsonb(r) AS body, false AS principal FROM public.course_revision_source r WHERE r.athlete_id=$1 AND r.course_id::text=$2->>'sourceId' AND r.course_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.course_revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.course_revision v WHERE v.athlete_id=r.athlete_id AND v.course_id=r.course_id AND v.course_revision=r.course_revision AND v.revision_id::text=$2->>'revisionId')$query$;
    WHEN 'course-head-descriptor' THEN q:=$query$SELECT 'current_head'::text AS role, 'course'::text AS relation, jsonb_build_array(r.course_id,r.head_revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.course r WHERE r.athlete_id=$1 AND r.course_id::text=$2->>'sourceId' AND r.course_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.head_revision::numeric=($2->>'revision')::numeric AND r.status='available' AND NOT EXISTS(SELECT 1 FROM public.export_course_deletions() d WHERE d.athlete_id=r.athlete_id AND d.course_id=r.course_id)$query$;
    WHEN 'activity-track-descriptor' THEN q:=$query$SELECT 'immutable_descriptor'::text AS role, 'activity_track_revision'::text AS relation, jsonb_build_array(r.activity_id,r.track_id,r.track_revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.activity_track_revision r WHERE r.athlete_id=$1 AND r.activity_id::text=$2->>'sourceId' AND r.activity_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.track_id::text=$2->>'trackId' AND r.track_id=CASE WHEN $2->>'trackId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'trackId')::uuid ELSE NULL END AND r.track_revision::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM public.activity_canonical a JOIN public.activity_source_head h ON h.athlete_id=a.athlete_id AND h.activity_id=a.id WHERE a.athlete_id=r.athlete_id AND a.id=r.activity_id AND NOT a.deleted AND h.kind=r.source_kind AND h.source_id=r.source_id AND h.source_revision=r.source_revision AND NOT EXISTS(SELECT 1 FROM public.activity_suppression z WHERE z.athlete_id=h.athlete_id AND z.kind=h.kind AND z.source_id=h.source_id))$query$;
    WHEN 'resource-text-version' THEN q:=$query$SELECT 'immutable_version'::text AS role, 'resource_version'::text AS relation, jsonb_build_array(r.resource_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.resource_version r WHERE r.athlete_id=$1 AND r.resource_id::text=$2->>'sourceId' AND r.resource_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.version_id::text=$2->>'versionId' AND r.version_id=CASE WHEN $2->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'versionId')::uuid ELSE NULL END AND EXISTS(SELECT 1 FROM public.resource h WHERE h.athlete_id=r.athlete_id AND h.id=r.resource_id AND h.deleted_at IS NULL AND h.source_kind='text')
 UNION ALL
 SELECT 'current_head'::text AS role, 'resource'::text AS relation, jsonb_build_array(r.id) AS key, to_jsonb(r) AS body, false AS principal FROM public.resource r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END$query$;
    WHEN 'race-timing-pin-fragment' THEN q:=$query$SELECT 'pin_membership'::text AS role, 'nutrition_plan_version'::text AS relation, jsonb_build_array(r.plan_id,r.version_id) AS key, to_jsonb(r) AS body, true AS principal FROM public.nutrition_plan_version r WHERE r.athlete_id=$1 AND EXISTS(SELECT 1 FROM jsonb_array_elements($4) requested WHERE requested->>'kind'='nutrition-plan-version' AND requested->>'sourceId'=r.plan_id::text AND requested->>'versionId'=r.version_id::text) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.record_json->'raceTimingPins','[]'::jsonb)) p WHERE p->>'eventId'=$2->>'sourceId' AND (p->>'eventRevision')::numeric=($2->>'revision')::numeric AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.record_json->'itemRaceTimingBindings','[]'::jsonb)) b JOIN LATERAL jsonb_array_elements(r.record_json->'items') item ON item->>'id'=b->>'itemId' WHERE b->'binding'->>'state'='captured' AND b->'binding'->>'eventId'=p->>'eventId' AND (b->'binding'->>'eventRevision')::numeric=(p->>'eventRevision')::numeric AND item->'anchor'->>'kind'='relative' AND item->'anchor'->>'entity'='race' AND item->'anchor'->>'entityId'=p->>'eventId'))$query$;
    WHEN 'gallery-descriptor' THEN q:=$query$SELECT 'current_descriptor'::text AS role, 'gallery_media_item'::text AS relation, jsonb_build_array(r.id,r.access_revision) AS key, to_jsonb(r) AS body, true AS principal FROM public.gallery_media_item r WHERE r.athlete_id=$1 AND r.id::text=$2->>'sourceId' AND r.id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END AND r.access_revision::numeric=($2->>'accessRevision')::numeric AND r.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.gallery_media_object o WHERE o.athlete_id=r.athlete_id AND o.storage_ref=r.storage_ref AND o.content_hash=r.content_hash AND o.size_bytes=r.size_bytes AND o.media_type=r.media_type) AND NOT EXISTS(SELECT 1 FROM public.gallery_media_derivative d WHERE d.athlete_id=r.athlete_id AND d.media_item_id=r.id AND NOT EXISTS(SELECT 1 FROM public.gallery_media_object o WHERE o.athlete_id=d.athlete_id AND o.storage_ref=d.storage_ref AND o.content_hash=d.content_hash AND o.size_bytes=d.size_bytes AND o.media_type=d.media_type))
 UNION ALL
 SELECT 'preview_descriptor'::text AS role, 'gallery_media_derivative'::text AS relation, jsonb_build_array(r.media_item_id,r.kind) AS key, to_jsonb(r) AS body, false AS principal FROM public.gallery_media_derivative r WHERE r.athlete_id=$1 AND r.media_item_id::text=$2->>'sourceId' AND r.media_item_id=CASE WHEN $2->>'sourceId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN ($2->>'sourceId')::uuid ELSE NULL END
 UNION ALL
 SELECT 'original_ledger'::text AS role, 'gallery_media_object'::text AS relation, jsonb_build_array(r.storage_ref) AS key, to_jsonb(r) AS body, false AS principal FROM public.gallery_media_object r WHERE r.athlete_id=$1 AND EXISTS(SELECT 1 FROM public.gallery_media_item m WHERE m.athlete_id=r.athlete_id AND m.id::text=$2->>'sourceId' AND m.access_revision::numeric=($2->>'accessRevision')::numeric AND m.deleted_at IS NULL AND m.storage_ref=r.storage_ref AND m.content_hash=r.content_hash AND m.size_bytes=r.size_bytes AND m.media_type=r.media_type)
 UNION ALL
 SELECT 'preview_ledger'::text AS role, 'gallery_media_object'::text AS relation, jsonb_build_array(r.storage_ref) AS key, to_jsonb(r) AS body, false AS principal FROM public.gallery_media_object r WHERE r.athlete_id=$1 AND EXISTS(SELECT 1 FROM public.gallery_media_derivative d WHERE d.athlete_id=r.athlete_id AND d.media_item_id::text=$2->>'sourceId' AND d.storage_ref=r.storage_ref AND d.content_hash=r.content_hash AND d.size_bytes=r.size_bytes AND d.media_type=r.media_type)$query$;
   END CASE;
   projection:='WITH relations AS MATERIALIZED ('||q||') SELECT count(*)::bigint,
    count(*) FILTER(WHERE principal)::bigint,
    coalesce(sum(octet_length(body::text)),0)::bigint,
    coalesce(max(octet_length(body::text)),0)::bigint,';
   -- Separate SQL text: an aggregate nested inside CASE could still evaluate its
   -- hash arguments during the scalar pass. No row fingerprint exists in pass1.
   IF phase=1 THEN projection:=projection||'NULL::jsonb FROM relations';
   ELSE projection:=projection||'coalesce(jsonb_agg(jsonb_build_object(''role'',role,''relation'',relation,''key'',CASE WHEN relation=''gallery_media_object'' THEN jsonb_build_array(encode(sha256(convert_to(key->>0,''UTF8'')),''hex'')) ELSE key END,
      ''hashMethod'',''postgres-owned-relation-row-jsonb-utc-v2'',
      ''sourceRowDigest'',encode(sha256(convert_to(body::text,''UTF8'')),''hex''))
      ORDER BY role COLLATE "C",relation COLLATE "C",CASE WHEN relation=''gallery_media_object'' THEN jsonb_build_array(encode(sha256(convert_to(key->>0,''UTF8'')),''hex'')) ELSE key END::text COLLATE "C"),''[]''::jsonb) FROM relations';
   END IF;
   EXECUTE projection INTO n,principal_count,bytes,maximum,relations USING tenant,i,phase=2,normalized;
   IF phase=1 THEN
    total_bytes:=total_bytes+bytes+CASE WHEN k='gallery-descriptor' THEN 16384 ELSE 0 END; total_rows:=total_rows+n;
    IF maximum>4194304 OR total_bytes>4194304 OR total_rows>5000 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_SOURCE_BOUND'; END IF;
   ELSE
    IF principal_count=0 THEN relations:='[]'::jsonb; END IF;
    cleanup:=NULL;
    -- Narrow cleanup observation is explicitly not a raw private queue-row fingerprint.
    IF k='gallery-descriptor' AND principal_count=1 THEN
     IF to_regprocedure('public.read_race_media_cleanup(uuid,integer)') IS NOT NULL THEN
      SELECT source INTO cleanup FROM public.read_race_media_cleanup((i->>'sourceId')::uuid,(i->>'accessRevision')::integer);
      IF octet_length(cleanup::text)>16384 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_SOURCE_BOUND'; END IF;
     END IF;
    END IF;
    IF k<>'race-timing-pin-fragment' AND principal_count>1 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_AMBIGUOUS_SOURCE'; END IF;
    fact:=jsonb_build_object('ordinal',ordinal,'identity',i,
     'state',CASE WHEN principal_count=0 OR (k='gallery-descriptor' AND (cleanup IS NULL OR cleanup->>'state'='unavailable')) THEN 'unavailable' ELSE 'observed' END,
     'reason',CASE WHEN principal_count=0 AND k IN ('routine-timer','gallery-descriptor','activity-overlay','activity-canonical-values','course-head-descriptor') THEN 'historical_observation_unavailable'
       WHEN principal_count=0 THEN 'source_unavailable' WHEN k='gallery-descriptor' AND (cleanup IS NULL OR cleanup->>'state'='unavailable') THEN 'cleanup_observation_unavailable' ELSE NULL END,
     'relations',relations,
     'relationGroupHashMethod','postgres-owned-relation-group-jsonb-v2',
     'relationGroupDigest',CASE WHEN principal_count=0 THEN NULL ELSE encode(sha256(convert_to(relations::text,'UTF8')),'hex') END,
     'cleanupHashMethod','postgres-narrow-cleanup-observation-jsonb-v1',
     'cleanupObservationDigest',CASE WHEN cleanup IS NULL THEN NULL ELSE encode(sha256(convert_to(cleanup::text,'UTF8')),'hex') END);
    result_bytes:=result_bytes+octet_length(fact::text)+2;
    IF result_bytes>4194304 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_OUTPUT_BOUND'; END IF;
    facts:=array_append(facts,fact);
   END IF;
  END LOOP;
 END LOOP;
 result:=jsonb_build_object('bindingVersion',2,'scope','prepared_full_context_relation_groups_only',
  'hashMethod','postgres-owned-relation-row-jsonb-utc-v2',
  'sqlRefsDigest',encode(sha256(convert_to(normalized::text,'UTF8')),'hex'),
  'transactionId',txid_current()::text,'callerRole',current_user,'athleteId',tenant,'rows',to_jsonb(facts),
  'storage','not_persisted','admissionAllowed',false,'sourceCompleteness','unverified','authority','none','freshness','not_checked');
 IF octet_length(result::text)>4194304 THEN RAISE EXCEPTION 'MANUAL_FULL_BINDING_OUTPUT_BOUND'; END IF;
 RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION public.observe_manual_review_full_owned_source_bindings_v2(jsonb) FROM PUBLIC;
